mapper.select:
select * from (SELECT T.* FROM(
SELECT #{DELIVERY_STATUS_01} settleStatus, #{DELIVERY_STATUS_NAME01} settleStatusStr, T1.TOTLE_TRADE_ID tradeId, to_char(T1.TRADE_DATE,'yyyy-MM-dd') tradeDate, to_char(T1.SETTLE_DATE,'yyyy-MM-dd') settleDate, T2.FINPROD_MARKET_ID finprodMarketId, T2.FINPROD_ABBR finprodAbbr, T1.FINPROD_TYPE2 finprodType2, sdl1.item_value finprodType2Str, btm.busi_type tgBusiType, sdl2.item_value tgBusiTypeStr, T1.PS ps, sdl3.item_value psStr, T1.SHARE_AMT*100 settleNum, T1.TRADE_AMT settleAmt, LISTAGG(T4.PORTFOLIO_ID,';') WITHIN GROUP (ORDER BY (T1.TOTLE_TRADE_ID)) portfolioId, LISTAGG(T5.PORTFOLIO_NAME,';') WITHIN GROUP (ORDER BY (T1.TOTLE_TRADE_ID)) portfolioName, case when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus01} THEN #{cleanStatus01} when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus02} THEN #{cleanStatus02} when T9.PS = #{feePs02} and (T9.SETTLE_STATUS is null or T9.SETTLE_STATUS = #{settlementStatus02}) and T9.ORDER_RET_STATUS = '03' THEN #{cleanStatus03} ELSE NULL END cleanStatus, T1.TRADE_MARKET tradeMarket, sdl4.item_value tradeMarketStr, T1.TRADE_PLAT tradePlat, sdl5.item_value tradePlatStr, T7.SEC_ACCT_NAME secAcctId, T6.PARTY_NAME counterName, T1.TRADE_MARKET_MODE tradeMarketMode, sdl6.item_value tradeMarketModeStr, NULL AS cleanStlStatus, NULL AS cleanArgStatus, NULL settleSeqNo, T1.FINPROD_ID finprodId, T1.CCY ccy, decode(T1.PS,#{PS_T07},'04',#{PS_T08},'04',#{PS_T09},'04',#{PS_T39},'03',#{PS_T03},'01',#{PS_T01},'02',#{PS_T02},'02','02') spcdCode FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD T4 ON T3.TRADE_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T4.PORTFOLIO_ID = T5.PORTFOLIO_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO T6 ON T1.COUNTER_ID = T6.PARTY_ID LEFT JOIN STL_SEC_ACCT_INFO T7 ON T1.SEC_MANAGE_ACCT_ID = T7.SEC_ACCT_ID LEFT JOIN TRD_BANK_MANUAL_SETTLE_INFO T8 ON T1.TOTLE_TRADE_ID = T8.TRADE_ID LEFT JOIN STL_PAY_ORDERS T9 ON T1.TOTLE_TRADE_ID = T9.TRADE_ID LEFT JOIN INF_PAY_ORDERS_STATUS T10 ON T9.ORDER_ID = T10.ORDER_ID LEFT JOIN SYS_DATADICT_LIST sdl on sdl.dict_code ='DELIVERY_STATUS' and sdl.item_code = T8.Settle_Status LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='FINPROD_TYPE_TG' and sdl1.item_code = T1.FINPROD_TYPE2 LEFT JOIN BUSI_TYPE_MAPPING btm ON T1.FINPROD_TYPE2 = btm.Finprod_Type_Tg AND T1.Ps = btm.ps LEFT JOIN SYS_DATADICT_LIST sdl2 on sdl2.dict_code ='BUSI_TYPE_POSITION' and sdl2.item_code = btm.busi_type LEFT JOIN SYS_DATADICT_LIST sdl3 on sdl3.dict_code ='PS' and sdl3.item_code = T1.PS LEFT JOIN SYS_DATADICT_LIST sdl4 on sdl4.dict_code ='TRADE_PLACE' and sdl4.item_code = T1.TRADE_MARKET LEFT JOIN SYS_DATADICT_LIST sdl5 on sdl5.dict_code ='SHARES_TRADE_PLATFORM' and sdl5.item_code = T1.TRADE_PLAT LEFT JOIN SYS_DATADICT_LIST sdl6 on sdl6.dict_code ='SHARES_TRADE_MARKET' and sdl6.item_code = T1.TRADE_MARKET_MODE WHERE T8.SETTLE_SEQ_NO IS NULL
AND T1.TG_BUSI_TYPE IN (#{PINAN_BUSINESS_TYPE_09},#{PINAN_BUSINESS_TYPE_10},#{PINAN_BUSINESS_TYPE_11}, #{PINAN_BUSINESS_TYPE_35},#{PINAN_BUSINESS_TYPE_36},#{PINAN_BUSINESS_TYPE_36}, #{PINAN_BUSINESS_TYPE_20},#{PINAN_BUSINESS_TYPE_51},#{PINAN_BUSINESS_TYPE_52}, #{PINAN_BUSINESS_TYPE_74},#{PINAN_BUSINESS_TYPE_75},#{PINAN_BUSINESS_TYPE_76},#{PINAN_BUSINESS_TYPE_77}, #{PINAN_BUSINESS_TYPE_105},#{PINAN_BUSINESS_TYPE_106},#{PINAN_BUSINESS_TYPE_107},#{PINAN_BUSINESS_TYPE_108}) AND T1.TRADE_STATUS =#{TRADE_STATUS_01} AND T1.Is_Cancel =#{isCalcN} AND T1.SETTLE_DATE >= #{settleDateStart} AND T1.SETTLE_DATE <= #{settleDateEnd}
AND T4.PORTFOLIO_ID IN(
#{item}
)
AND T2.FINPROD_MARKET_ID IN(
#{item}
)
AND T1.TOTLE_TRADE_ID= #{tradeId}
AND T1.Finprod_Type2= #{finprodType2}
AND btm.busi_type = #{tgBusiType}
AND T1.PS= #{ps}
AND T1.TRADE_DATE= #{tradeDate}
GROUP BY T8.SETTLE_STATUS, T1.TOTLE_TRADE_ID, T1.TRADE_DATE, T1.SETTLE_DATE, T2.FINPROD_MARKET_ID, T2.FINPROD_ABBR, T1.FINPROD_TYPE2, sdl1.item_value, btm.busi_type, sdl2.item_value, T1.PS, sdl3.item_value, T1.SHARE_AMT, T1.TRADE_AMT, T9.PS, T9.SETTLE_STATUS, T9.ORDER_RET_STATUS, T1.TRADE_MARKET, sdl4.item_value, T1.TRADE_PLAT, sdl5.item_value, T6.PARTY_NAME, T1.FINPROD_ID, T1.CCY, T7.SEC_ACCT_NAME, T1.TRADE_MARKET_MODE, sdl6.item_value union all
SELECT T0.SETTLE_STATUS settleStatus, sdl.ITEM_VALUE settleStatusStr, T1.TOTLE_TRADE_ID tradeId, to_char(T1.TRADE_DATE,'yyyy-MM-dd') tradeDate, to_char(T0.SETTLE_DATE,'yyyy-MM-dd') settleDate, T2.FINPROD_MARKET_ID finprodMarketId, T2.FINPROD_ABBR finprodAbbr, T1.FINPROD_TYPE2 finprodType2, sdl1.item_value finprodType2Str, btm.busi_type tgBusiType, sdl2.item_value tgBusiTypeStr, T1.PS ps, sdl3.item_value psStr, T0.SETTLE_NUM settleNum, T0.SETTLE_AMT settleAmt, LISTAGG(T4.PORTFOLIO_ID,';') WITHIN GROUP (ORDER BY (T1.TOTLE_TRADE_ID)) portfolioId, LISTAGG(T5.PORTFOLIO_NAME,';') WITHIN GROUP (ORDER BY (T1.TOTLE_TRADE_ID)) portfolioName, case when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus01} THEN #{cleanStatus01} when T9.PS = #{feePs02} and T9.SETTLE_STATUS = #{settlementStatus01} and T9.ORDER_RET_STATUS = #{commandDealStatus02} THEN #{cleanStatus02} when T9.PS = #{feePs02} and (T9.SETTLE_STATUS is null or T9.SETTLE_STATUS = #{settlementStatus02}) and T9.ORDER_RET_STATUS = '03' THEN #{cleanStatus03} ELSE NULL END cleanStatus, T1.TRADE_MARKET tradeMarket, sdl4.item_value tradeMarketStr, T1.TRADE_PLAT tradePlat, sdl5.item_value tradePlatStr, T7.SEC_ACCT_NAME secAcctId, T6.COUNTER_NAME counterName, T1.TRADE_MARKET_MODE tradeMarketMode, sdl6.item_value tradeMarketModeStr, NULL AS cleanStlStatus, NULL AS cleanArgStatus, T0.SETTLE_SEQ_NO settleSeqNo, T0.FINPROD_ID finprodId, T1.CCY ccy, decode(T1.PS,#{PS_T07},'04',#{PS_T08},'04',#{PS_T09},'04',#{PS_T39},'03',#{PS_T03},'01',#{PS_T01},'02',#{PS_T02},'02','02') spcdCode FROM TRD_BANK_MANUAL_SETTLE_INFO T0 LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL T1 ON T0.TRADE_ID =T1.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD T4 ON T3.TRADE_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T4.PORTFOLIO_ID = T5.PORTFOLIO_ID LEFT JOIN MST_COUNTER_PARTY T6 ON T1.COUNTER_ID = T6.COUNTER_ID LEFT JOIN STL_SEC_ACCT_INFO T7 ON T1.SEC_MANAGE_ACCT_ID = T7.SEC_ACCT_ID LEFT JOIN STL_PAY_ORDERS T9 ON T1.TOTLE_TRADE_ID = T9.TRADE_ID LEFT JOIN INF_PAY_ORDERS_STATUS T10 ON T9.ORDER_ID = T10.ORDER_ID LEFT JOIN SYS_DATADICT_LIST sdl on sdl.dict_code ='DELIVERY_STATUS' and sdl.item_code = T0.Settle_Status LEFT JOIN SYS_DATADICT_LIST sdl1 on sdl1.dict_code ='FINPROD_TYPE_TG' and sdl1.item_code = T1.FINPROD_TYPE2 LEFT JOIN BUSI_TYPE_MAPPING btm ON T1.FINPROD_TYPE2 = btm.Finprod_Type_Tg AND T1.Ps = btm.ps LEFT JOIN SYS_DATADICT_LIST sdl2 on sdl2.dict_code ='BUSI_TYPE_POSITION' and sdl2.item_code = btm.busi_type LEFT JOIN SYS_DATADICT_LIST sdl3 on sdl3.dict_code ='PS' and sdl3.item_code = T1.PS LEFT JOIN SYS_DATADICT_LIST sdl4 on sdl4.dict_code ='TRADE_PLACE' and sdl4.item_code = T1.TRADE_MARKET LEFT JOIN SYS_DATADICT_LIST sdl5 on sdl5.dict_code ='SHARES_TRADE_PLATFORM' and sdl5.item_code = T1.TRADE_PLAT LEFT JOIN SYS_DATADICT_LIST sdl6 on sdl6.dict_code ='SHARES_TRADE_MARKET' and sdl6.item_code = T1.TRADE_MARKET_MODE WHERE T1.TRADE_STATUS =#{TRADE_STATUS_01} AND T1.Is_Cancel =#{isCalcN} AND T0.SETTLE_DATE >= #{settleDateStart} AND T0.SETTLE_DATE <= #{settleDateEnd}
AND T0.SETTLE_STATUS IN
#{item}
AND T4.PORTFOLIO_ID IN(
#{item}
)
AND T2.FINPROD_MARKET_ID IN(
#{item}
)
AND T1.TOTLE_TRADE_ID= #{tradeId}
AND T1.Finprod_Type2= #{finprodType2}
AND btm.busi_type= #{tgBusiType}
AND T1.PS= #{ps}
AND T1.TRADE_DATE= #{tradeDate}
GROUP BY T0.SETTLE_STATUS, T1.TOTLE_TRADE_ID, T1.TRADE_DATE, T0.SETTLE_DATE, T2.FINPROD_MARKET_ID, T2.FINPROD_ABBR, T1.FINPROD_TYPE2, sdl.ITEM_VALUE, sdl1.item_value, btm.busi_type, sdl2.item_value, T1.PS, sdl3.item_value, T0.SETTLE_NUM, T0.SETTLE_AMT, T9.PS, T9.SETTLE_STATUS, T9.ORDER_RET_STATUS, T1.TRADE_MARKET, sdl4.item_value, T1.TRADE_PLAT, sdl5.item_value, T6.COUNTER_NAME, T0.SETTLE_SEQ_NO, T0.FINPROD_ID, T1.CCY, T7.SEC_ACCT_NAME, T1.TRADE_MARKET_MODE, sdl6.item_value)t left join SYS_DATADICT_LIST sdl on sdl.DICT_CODE='SETTLE_STATUS' and t.cleanStatus=sdl.ITEM_CODE
order by t.settleStatus,t.settleDate,t.finprodType2,t.tgBusiType,t.finprodMarketId,t.cleanStatus)
order by ${sort} ${direction}

if.where:
(t.settleStatusStr like '%' || #{search} || '%'
OR t.tradeId like '%' || #{search} || '%'
OR t.tradeDate = #{search}
OR t.tradeDate= #{year}||'-'||#{search}
OR replace(t.tradeDate,'-','/')=#{search}
OR replace(t.tradeDate,'-','/')=#{year}||'/'||#{search}
OR t.settleDate = #{search}
OR t.settleDate= #{year}||'-'||#{search}
OR replace(t.settleDate,'-','/')=#{search}
OR replace(t.settleDate,'-','/')=#{year}||'/'||#{search}
OR t.finprodMarketId like '%' || #{search} || '%'
OR t.finprodAbbr like '%' || #{search} || '%'
OR T.finprodType2Str like '%' || #{search} || '%'
OR T.psStr like '%' || #{search} || '%'
OR t.settleNum||'' = #{search}
OR t.settleAmt||'' = #{search}
OR t.portfolioId like '%' || #{search} || '%'
OR t.portfolioName like '%' || #{search} || '%'
OR sdl.ITEM_VALUE like '%' || #{search} || '%'
OR T.tradeMarketStr like '%' || #{search} || '%'
OR T.tradePlatStr like '%' || #{search} || '%'
OR T.secAcctId like '%' || #{search} || '%'
OR T.counterName like '%' || #{search} || '%'
)

mapper.select:
SELECT P.ACCT_NO CASHACCTID
FROM PTL_CAPACCT_INFO P
LEFT JOIN STL_CAPACCT_INFO S ON P.ACCT_NO = S.ACCT_NO
where P.PORTFOLIO_ID = #{portfolioId}
AND P.ACCT_TYPE = #{acctType}
AND P.CCY =#{ccy}
and rownum=1

